//! 📥️ The completed preview receiver moves canonical mesh ownership into the original paid index.
use super::*;
use semio_framework::{MeshData,MeshCanonicalDecoder,MeshCanonicalIntakeSource};
use semio_framework_value::{DslValue,Number};
use semio_framework_job::{StepContext,OriginalTurnFailure,InteractiveJobCloseStep};
use protocol::causal::transition::HistoryFoldIndexInsert;
use std::{cmp::Ordering,mem::{ManuallyDrop,size_of}};
const KEYS:[&str;11]=["done","cancellable","phase","unitsDone","unitsTotal","nodeHash","windowId","windowKindId","handle","tolerance","mesh"];
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
pub fn admitted(d:RetirementDemand,g:RetainedCloneGrant)->bool{g.maximum_items!=0&&d.copy_bytes<=g.maximum_copy_bytes&&d.capacity_bytes<=g.maximum_capacity_bytes&&d.release_bytes<=g.maximum_release_bytes&&d.depth<=g.maximum_depth}
pub fn object(source:&DslValue)->Result<&[(String,DslValue)],ValueError>{match source{DslValue::Object(rows)=>Ok(rows),_=>Err(invalid("original completed preview requires an object"))}}
fn object_mut(source:&mut DslValue)->Result<&mut[(String,DslValue)],ValueError>{match source{DslValue::Object(rows)=>Ok(rows),_=>Err(invalid("original completed preview requires an object"))}}
pub fn text(source:&DslValue)->Result<&str,ValueError>{match source{DslValue::String(value)=>Ok(value),_=>Err(invalid("original completed preview requires text"))}}
fn uint(source:&DslValue)->Result<u64,ValueError>{match source{DslValue::Number(value)=>value.as_u64().ok_or_else(||invalid("original completed preview requires UInt64")),_=>Err(invalid("original completed preview requires UInt64"))}}
fn compare_demand(left:&String,right:&String,offset:usize,body:usize)->Result<RetirementDemand,ValueError>{let remaining=left.len().min(right.len()).saturating_sub(offset);Ok(RetirementDemand{copy_bytes:if remaining==0{0}else{remaining.min((body/2).max(1))*2},depth:1,..Default::default()})}
fn compare_step(left:&String,right:&String,offset:usize,grant:RetainedCloneGrant)->Result<(Option<Ordering>,usize,RetainedCloneProgress),ValueError>{let demand=compare_demand(left,right,offset,grant.maximum_copy_bytes)?;if !admitted(demand,grant){return Ok((None,offset,Default::default()))}let end=offset+demand.copy_bytes/2;let order=left.as_bytes()[offset..end].cmp(&right.as_bytes()[offset..end]);Ok(((order!=Ordering::Equal||end==left.len().min(right.len())).then(||if order==Ordering::Equal{left.len().cmp(&right.len())}else{order}),end,RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))}
/// 🪪️ Original business addressing is borrowed unchanged throughout receiving and cache admission.
pub struct FlowPreviewCompletedAddress<'a>{pub window_id:&'a str,pub window_kind_id:&'a str,pub handle:&'a str,pub node_hash:u64,pub tolerance:f64}
impl FlowPreviewCompletedAddress<'_>{fn binding(&self)->[u64;8]{[self.window_id.as_ptr()as u64,self.window_id.len()as u64,self.window_kind_id.as_ptr()as u64,self.window_kind_id.len()as u64,self.handle.as_ptr()as u64,self.handle.len()as u64,self.node_hash,self.tolerance.to_bits()]}}
#[derive(semio_framework_value::RetireOwned)]
struct Fields{source:Option<DslValue>,mesh:Option<MeshData>,insertion:Option<HistoryFoldIndexInsert<String,MeshData>>,displaced:Option<ControlledRetirement<(String,MeshData)>>}
/// 🧳️ Intake refusal returns the exact parsed input or the whole original receiver.
pub enum FlowPreviewCompletedIntakeSource{Value(DslValue),Receiver(FlowPreviewCompletedReceiver)}
/// 🧵️ Every partial field and the original handle remain in custody until paid commit or full close.
pub struct FlowPreviewCompletedReceiver{origin:(u64,u64),binding:Option<[u64;8]>,fields:ManuallyDrop<Option<Fields>>,decoder:Option<MeshCanonicalDecoder>,source_close:Option<ControlledRetirement<DslValue>>,close:Option<ControlledRetirement<Fields>>,scan:usize,slots:[usize;11],field:Option<usize>,offset:usize,phase:u8,closing:bool,committed:bool,complete:bool,received:bool,units_done:u64,units_total:u64,progress_phase:PreviewTessellatePhase}
impl FlowPreviewCompletedReceiver{
 pub fn new(source:DslValue,cx:&mut StepContext<'_>)->Result<Self,(OriginalTurnFailure,FlowPreviewCompletedIntakeSource)>{
  if cx.is_cancelled()||cx.should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Err((invalid("original completed preview intake awaits admission").into(),FlowPreviewCompletedIntakeSource::Value(source)))}
  cx.consume_fuel(1);if object(&source).is_err()||!matches!(object(&source).unwrap().len(),10|11){return Err((invalid("original completed preview member shape is invalid").into(),FlowPreviewCompletedIntakeSource::Value(source)))}
  let complete=object(&source).unwrap().len()==11;let receiver=Self{origin:(cx.operation().0,cx.generation().0),binding:None,fields:ManuallyDrop::new(Some(Fields{source:Some(source),mesh:None,insertion:None,displaced:None})),decoder:None,source_close:None,close:None,scan:0,slots:[usize::MAX;11],field:None,offset:0,phase:0,closing:false,committed:false,complete,received:false,units_done:0,units_total:0,progress_phase:PreviewTessellatePhase::Idle};
  if let Err(error)=cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}){return Err((error.into(),FlowPreviewCompletedIntakeSource::Receiver(receiver)))}Ok(receiver)
 }
 pub fn next_demands(&self,index:&HistoryFoldIndex<String,MeshData>,body:usize)->Result<RetirementDemand,ValueError>{
  if self.closing{return self.next_close_demands(body)}if self.terminal_is_empty(){return Ok(Default::default())}
  let mut demand=match self.phase{
   0=>{let fields=self.fields.as_ref().unwrap();let rows=object(fields.source.as_ref().unwrap())?;match self.field{None=>RetirementDemand{copy_bytes:rows.get(self.scan).map_or(0,|(key,_)|key.len().min(14)),depth:1,..Default::default()},Some(field)=>RetirementDemand{copy_bytes:match field{0|1=>size_of::<bool>(),2=>text(&rows[self.scan].1)?.len().min(13),3..=5|9=>size_of::<Number>()+size_of::<u64>(),6..=8=>text(&rows[self.scan].1)?.len().saturating_sub(self.offset).min((body/2).max(1))*2,_=>0},depth:1,..Default::default()}}},
   1|3|5|7=>RetirementDemand{depth:1,..Default::default()},
   2=>self.decoder.as_ref().unwrap().next_demands(body)?,
   4=>self.decoder.as_ref().unwrap().next_close_demands(body)?,
   6=>self.source_close.as_ref().unwrap().selected_demand(body)?,
   10=>self.fields.as_ref().unwrap().displaced.as_ref().unwrap().selected_demand(body)?,
   8|9=>self.fields.as_ref().unwrap().insertion.as_ref().unwrap().next_demands(index,body,compare_demand)?,
   _=>return Err(invalid("original completed preview receiver phase is invalid")),
  };demand.depth=demand.depth.max(1);Ok(demand)
 }
 pub fn step(&mut self,address:&FlowPreviewCompletedAddress<'_>,index:&mut HistoryFoldIndex<String,MeshData>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.closing{return Err(invalid("original completed preview receiver is closing").into())}if self.terminal_is_empty(){return Ok(self.committed)}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let grant=cx.retained_grant();let demand=self.next_demands(index,grant.maximum_copy_bytes)?;if !admitted(demand,grant){return Ok(false)}
  if self.origin!=(cx.operation().0,cx.generation().0)||self.binding.is_some_and(|binding|binding!=address.binding()){cx.consume_fuel(1);return Err(invalid("original completed preview initiating source changed").into())}self.binding=Some(address.binding());
  match self.phase{
   1=>{let fields=self.fields.as_mut().unwrap();let value=std::mem::replace(&mut object_mut(fields.source.as_mut().unwrap())?[self.slots[10]].1,DslValue::Null);match MeshCanonicalDecoder::new(value,cx){Ok(decoder)=>{self.decoder=Some(decoder);self.phase=2;},Err((error,source))=>{match source{MeshCanonicalIntakeSource::Value(value)=>object_mut(fields.source.as_mut().unwrap())?[self.slots[10]].1=value,MeshCanonicalIntakeSource::Decoder(decoder)=>self.decoder=Some(decoder)}return Err(error)}}return Ok(false)},
   2=>{if self.decoder.as_mut().unwrap().step(cx)?{self.phase=3;}return Ok(false)},
   3=>{if let Some(mesh)=self.decoder.as_mut().unwrap().take(cx)?{self.fields.as_mut().unwrap().mesh=Some(mesh);self.decoder.as_mut().unwrap().begin_close();self.phase=4;}return Ok(false)},
   4=>{self.decoder.as_mut().unwrap().close_step(cx)?;if self.decoder.as_ref().unwrap().terminal_is_empty(){self.decoder=None;self.phase=5;}return Ok(false)},
   6=>{semio_framework_job::close_original_retained_step(cx,demand,|grant|self.source_close.as_mut().unwrap().step(grant))?;if self.source_close.as_ref().unwrap().terminal_is_empty(){self.source_close=None;if self.complete{self.phase=8}else{self.fields.take();self.received=true;}}return Ok(false)},
   10=>{semio_framework_job::close_original_retained_step(cx,demand,|g|self.fields.as_mut().unwrap().displaced.as_mut().unwrap().step(g))?;if self.fields.as_ref().unwrap().displaced.as_ref().unwrap().terminal_is_empty(){self.fields.as_mut().unwrap().displaced=None;self.fields.take();self.received=true;}return Ok(self.received)},
   _=>{},
  }
  cx.consume_fuel(1);let mut progress=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};let result=(||->Result<(),ValueError>{match self.phase{
   0=>{let rows=object(self.fields.as_ref().unwrap().source.as_ref().unwrap())?;if self.scan==rows.len(){if self.slots[..if self.complete{11}else{10}].contains(&usize::MAX)||self.units_done>self.units_total||(self.complete&&self.units_done!=self.units_total){return Err(invalid("original completed preview completion is inconsistent"))}self.phase=if self.complete{1}else{7};return Ok(())}let(key,value)=&rows[self.scan];let Some(field)=self.field else{if key.len()>14{return Err(invalid("original completed preview has an unknown member"))}let field=KEYS.iter().position(|candidate|*candidate==key).ok_or_else(||invalid("original completed preview has an unknown member"))?;if self.slots[field]!=usize::MAX{return Err(invalid("original completed preview has a duplicate member"))}self.slots[field]=self.scan;self.field=Some(field);return Ok(())};match field{
    0=>if !matches!(value,DslValue::Bool(done)if *done==self.complete){return Err(invalid("original completed preview is unfinished"))},
    1=>if !matches!(value,DslValue::Bool(cancellable)if *cancellable!=self.complete){return Err(invalid("original completed preview still reports cancellation"))},
    2=>{let phase=text(value)?;self.progress_phase=match phase{"complete" if self.complete=>PreviewTessellatePhase::Complete,"awaitingGrant" if !self.complete=>PreviewTessellatePhase::AwaitingGrant,"admittingSource" if !self.complete=>PreviewTessellatePhase::AdmittingSource,"validating" if !self.complete=>PreviewTessellatePhase::Validating,"samplingEdges" if !self.complete=>PreviewTessellatePhase::SamplingEdges,"meshingFaces" if !self.complete=>PreviewTessellatePhase::MeshingFaces,"packingEdges" if !self.complete=>PreviewTessellatePhase::PackingEdges,_=>return Err(invalid("original preview phase is invalid"))};},
    3=>self.units_done=uint(value)?,4=>self.units_total=uint(value)?,5=>if uint(value)?!=address.node_hash{return Err(invalid("original completed preview hash changed"))},
    6..=8=>{let source=text(value)?;let target=match field{6=>address.window_id,7=>address.window_kind_id,_=>address.handle};if source.len()!=target.len()||source.is_empty(){return Err(invalid("original completed preview business address changed"))}let end=self.offset+progress.copied_bytes/2;if source.as_bytes()[self.offset..end]!=target.as_bytes()[self.offset..end]{return Err(invalid("original completed preview business address changed"))}self.offset=end;if end<source.len(){return Ok(())}},
    9=>{let DslValue::Number(value)=value else{return Err(invalid("original completed preview tolerance is absent"))};let value=value.as_f64();if !value.is_finite()||value<=0.0||value.to_bits()!=address.tolerance.to_bits(){return Err(invalid("original completed preview tolerance changed"))}},10=>{},_=>unreachable!(),
   }self.offset=0;self.field=None;self.scan+=1;},
   5=>{let fields=self.fields.as_mut().unwrap();let source=&mut object_mut(fields.source.as_mut().unwrap())?[self.slots[8]].1;if !matches!(source,DslValue::String(_)){return Err(invalid("original completed preview handle ownership is absent"))}let DslValue::String(handle)=std::mem::replace(source,DslValue::Null)else{unreachable!()};fields.insertion=Some(HistoryFoldIndexInsert::new(handle,fields.mesh.take().unwrap()));self.phase=7;},
   7=>{self.source_close=Some(ControlledRetirement::new(self.fields.as_mut().unwrap().source.take().unwrap()).unwrap_or_else(|_|unreachable!()));self.phase=6;},
   8=>{let(ready,physical)=self.fields.as_mut().unwrap().insertion.as_mut().unwrap().step(index,RetainedCloneGrant{maximum_items:1,..grant},compare_step)?;progress=physical;if ready{self.phase=9;}},
   9=>{let(slot,original,physical)=self.fields.as_mut().unwrap().insertion.as_mut().unwrap().commit_or_replace_with(index,RetainedCloneGrant{maximum_items:1,..grant},|mesh|mesh)?;progress=physical;if slot.is_some(){self.fields.as_mut().unwrap().insertion=None;self.committed=true;if let Some(original)=original{self.fields.as_mut().unwrap().displaced=Some(ControlledRetirement::new(original).unwrap_or_else(|_|unreachable!()));self.phase=10;}else{self.fields.take();self.received=true;}}},
   _=>return Err(invalid("original completed preview receiver phase is invalid")),
  }Ok(())})();match result{Ok(())=>cx.consume_retained(progress)?,Err(error)=>return Err(OriginalTurnFailure::debit_original(if error.retained_progress()==Default::default(){error.with_retained_progress(progress)}else{error},cx))}Ok(self.committed)
 }
 pub fn received_progress(&self)->Option<PreviewTessellateProgress>{self.received.then_some(PreviewTessellateProgress{units_done:self.units_done,units_total:self.units_total,phase:self.progress_phase,..Default::default()})}
 pub fn begin_close(&mut self){self.closing=true;if let Some(decoder)=self.decoder.as_mut(){decoder.begin_close();}}
 pub fn next_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(decoder)=self.decoder.as_ref(){return decoder.next_close_demands(body)}if let Some(close)=self.source_close.as_ref(){return close.selected_demand(body)}if let Some(close)=self.close.as_ref(){return close.selected_demand(body)}Ok(RetirementDemand{depth:usize::from(self.fields.is_some()),..Default::default()})}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{
  self.begin_close();if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}if cx.should_yield(){return Ok(InteractiveJobCloseStep::Blocked)}if self.origin!=(cx.operation().0,cx.generation().0){cx.consume_fuel(1);return Err(invalid("original completed preview close initiating source changed").into())}
  if let Some(decoder)=self.decoder.as_mut(){let step=decoder.close_step(cx)?;if decoder.terminal_is_empty(){self.decoder=None;}return Ok(InteractiveJobCloseStep::Pending{progress:step.progress()})}
  let demand=self.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;
  let step=semio_framework_job::close_original_retained_step(cx,demand,|grant|{if let Some(close)=self.source_close.as_mut(){close.step(grant)}else if let Some(close)=self.close.as_mut(){close.step(grant)}else{self.close=Some(ControlledRetirement::new(self.fields.take().unwrap()).unwrap_or_else(|_|unreachable!()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}})?;
  if self.source_close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.source_close=None;}if self.close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.close=None;}Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})
 }
 pub fn terminal_is_empty(&self)->bool{self.fields.is_none()&&self.decoder.is_none()&&self.source_close.is_none()&&self.close.is_none()}
}
impl Drop for FlowPreviewCompletedReceiver{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original completed preview receiver requires full paid close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.fields)}}}}

#[derive(semio_framework_value::RetireOwned)]
enum LedgerRow{Handle((u64,String))}
#[derive(semio_framework_value::RetireOwned)]
struct LedgerFields{removed:Option<ControlledRetirement<LedgerRow>>,insertion:Option<HistoryFoldIndexInsert<u64,PreviewTessellateProgress>>}
/// 📒️ Each original request row closes before its admitted progress and addressed window settle.
pub struct FlowPreviewLedgerFold{origin:(u64,u64),hash:u64,progress:PreviewTessellateProgress,phase:u8,slot:usize,fields:ManuallyDrop<Option<LedgerFields>>,close:Option<ControlledRetirement<LedgerFields>>,closing:bool}
fn number_demand(_: &u64,_:&u64,_:usize,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:2*size_of::<u64>(),depth:1,..Default::default()})}
fn number_step(left:&u64,right:&u64,offset:usize,grant:RetainedCloneGrant)->Result<(Option<Ordering>,usize,RetainedCloneProgress),ValueError>{let d=number_demand(left,right,offset,grant.maximum_copy_bytes)?;if !admitted(d,grant){return Ok((None,offset,Default::default()))}Ok((Some(left.cmp(right)),0,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
impl FlowPreviewLedgerFold{
 pub fn new(hash:u64,progress:PreviewTessellateProgress,cx:&mut StepContext<'_>)->Result<Option<Self>,OriginalTurnFailure>{let d=RetirementDemand{copy_bytes:size_of::<u64>()+size_of::<PreviewTessellateProgress>(),depth:1,..Default::default()};if cx.is_cancelled()||cx.should_yield()||!admitted(d,cx.retained_grant()){return Ok(None)}let mut owner=Self{origin:(cx.operation().0,cx.generation().0),hash,progress,phase:0,slot:0,fields:ManuallyDrop::new(Some(LedgerFields{removed:None,insertion:None})),close:None,closing:false};cx.consume_fuel(1);if let Err(error)=cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}){owner.fields.take();return Err(error.into())}Ok(Some(owner))}
 pub fn next_demands(&self,session:&FlowEvalSession,window:&str,body:usize)->Result<RetirementDemand,ValueError>{
  if self.closing{return self.next_close_demands(body)}if self.terminal_is_empty(){return Ok(Default::default())}let fields=self.fields.as_ref().unwrap();if let Some(close)=fields.removed.as_ref(){return close.selected_demand(body)}
  if let Some(insertion)=fields.insertion.as_ref(){return insertion.next_demands(&session.tessellate_progress_by_hash,body,number_demand)}
  let depth=match self.phase{0=>session.pending_tessellate_by_hash.next_slot_depth_demand(self.slot)?.max(session.pending_tessellate_by_hash.next_extract_slot_depth_demand(self.slot)?),1=>session.tessellate_handle_by_hash.next_slot_depth_demand(self.slot)?.max(session.tessellate_handle_by_hash.next_extract_slot_depth_demand(self.slot)?),2=>session.tessellate_progress_by_hash.next_slot_depth_demand(self.slot)?,4=>{let key=flow_eval_window_key(window);session.window_tick_latches.next_insert_depth_demand(&key)?},_=>1};
  Ok(RetirementDemand{copy_bytes:match self.phase{0|1=>size_of::<u64>(),2=>size_of::<u64>()+size_of::<PreviewTessellateProgress>(),4=>window.len(),_=>0},depth:depth.max(1),..Default::default()})
 }
 pub fn step(&mut self,session:&mut FlowEvalSession,window:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.terminal_is_empty(){return Ok(true)}if self.closing{return Err(invalid("original preview ledger is closing").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let grant=cx.retained_grant();let demand=self.next_demands(session,window,grant.maximum_copy_bytes)?;if !admitted(demand,grant){return Ok(false)}if self.origin!=(cx.operation().0,cx.generation().0){cx.consume_fuel(1);return Err(invalid("original preview ledger initiating source changed").into())}
  if let Some(close)=self.fields.as_mut().unwrap().removed.as_mut(){semio_framework_job::close_original_retained_step(cx,demand,|g|close.step(g))?;if close.terminal_is_empty(){self.fields.as_mut().unwrap().removed=None;}return Ok(false)}
  cx.consume_fuel(1);let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};let result=(||->Result<(),ValueError>{match self.phase{
   0|1=>{let index=if self.phase==0{&mut session.state.pending_tessellate_by_hash}else{&mut session.state.tessellate_handle_by_hash};if self.slot==index.slot_count(){self.phase+=1;self.slot=0;}else{if index.slot_entry(self.slot).is_some_and(|(hash,_)|*hash==self.hash){let row=index.extract_slot_if(self.slot,|_,_|false).unwrap();self.fields.as_mut().unwrap().removed=Some(ControlledRetirement::new(LedgerRow::Handle(row)).unwrap_or_else(|_|unreachable!()));}self.slot+=1;}},
   2=>{let index=&mut session.state.tessellate_progress_by_hash;if self.slot==index.slot_count(){self.fields.as_mut().unwrap().insertion=Some(HistoryFoldIndexInsert::new(self.hash,self.progress));self.phase=3;}else if let Some((hash,progress))=index.slot_entry_mut(self.slot){if *hash==self.hash{*progress=self.progress;self.phase=4;}else{self.slot+=1;}}else{self.slot+=1;}},
   3=>{let insertion=self.fields.as_mut().unwrap().insertion.as_mut().unwrap();let(ready,physical)=insertion.step(&mut session.state.tessellate_progress_by_hash,RetainedCloneGrant{maximum_items:1,..grant},number_step)?;p=physical;if ready&&physical==Default::default(){let(slot,physical)=insertion.commit_with(&mut session.state.tessellate_progress_by_hash,RetainedCloneGrant{maximum_items:1,..grant},|progress|progress)?;p=physical;if slot.is_some(){self.fields.as_mut().unwrap().insertion=None;self.phase=4;}}},
   4=>{session.settle_window_extension(window,RetainedCloneGrant{maximum_items:1,..grant})?;self.fields.take();},_=>return Err(invalid("original preview ledger phase changed")),
  }Ok(())})();match result{Ok(())=>cx.consume_retained(p)?,Err(error)=>return Err(OriginalTurnFailure::debit_original(if error.retained_progress()==Default::default(){error.with_retained_progress(p)}else{error},cx))}Ok(self.terminal_is_empty())
 }
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn next_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close.as_ref().map_or(Ok(RetirementDemand{depth:usize::from(self.fields.is_some()),..Default::default()}),|close|close.selected_demand(body))}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{self.begin_close();if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}if self.origin!=(cx.operation().0,cx.generation().0){if cx.should_yield(){return Ok(InteractiveJobCloseStep::Blocked)}cx.consume_fuel(1);return Err(invalid("original preview ledger close initiating source changed").into())}let d=self.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=semio_framework_job::close_original_retained_step(cx,d,|grant|if let Some(close)=self.close.as_mut(){close.step(grant)}else{self.close=Some(ControlledRetirement::new(self.fields.take().unwrap()).unwrap_or_else(|_|unreachable!()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))})?;if self.close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.close=None;}Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})}
 pub fn terminal_is_empty(&self)->bool{self.fields.is_none()&&self.close.is_none()}
}
impl Drop for FlowPreviewLedgerFold{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original preview ledger requires full paid close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.fields)}}}}

